<script lang="ts">
 import {onMount}from'svelte';import{invoke}from'@tauri-apps/api/core';import UiIcon from './UiIcon.svelte';
 import type{HudProfile}from './launcher_plugins';import type{OverlaySnapshot}from './launcher_extensions';
 let{profile=$bindable(),frame,onchange}:{profile:HudProfile;frame:OverlaySnapshot;onchange:()=>void}=$props();
 let busy=$state(false),message=$state(''),background=$state('');
 async function refresh(){background=await invoke<string>('hud_title_background',{pid:frame.pid});}
 onMount(()=>{void refresh().catch(()=>{});});
 async function action(target:string){busy=true;message='';try{await invoke('hud_game_command',{pid:frame.pid,action:'title',values:{target}});}catch(e){message=String(e);}finally{busy=false;}}
 async function image(event:Event){const input=event.currentTarget as HTMLInputElement,file=input.files?.[0];if(!file)return;busy=true;try{if(file.size>20*1024*1024)throw new Error('El fondo debe ocupar menos de 20 MB.');const bitmap=await createImageBitmap(file);if(bitmap.width>8192||bitmap.height>8192){bitmap.close();throw new Error('La imagen supera 8192 píxeles.');}const canvas=document.createElement('canvas'),ratio=Math.min(1,3840/bitmap.width,2160/bitmap.height);canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();await invoke('hud_menu_background',{pid:frame.pid,dataUrl:canvas.toDataURL('image/png')});await refresh();}catch(e){message=String(e);}finally{busy=false;input.value='';}}
</script>
<section class="title-scene" style:--scene={background?`url('${background}')`:'none'} aria-label="Menú principal TP">
 <div class="ambient"></div><header><span>TP LAUNCHER <i>JAVA EDITION</i></span><div><label class="tool"><UiIcon name="image" size={15}/>Cambiar fondo<input disabled={busy} type="file" accept="image/png,image/jpeg,image/webp,image/gif" onchange={image}/></label><button disabled={busy} onclick={()=>{profile.title_theme=false;onchange();}}>Diseño Vanilla</button></div></header>
 <main><img class="brand" src="/logos/tp-launcher.svg" alt=""/><span class="edition">TU MUNDO. TU SIGUIENTE AVENTURA.</span><h1>TP LAUNCHER</h1><nav>{#each [['singleplayer','Un jugador','world'],['multiplayer','Multijugador','globe'],['options','Opciones','settings']] as [target,label,icon]}<button class:primary={target==='singleplayer'} disabled={busy||frame.telemetry?.labels?.['title_'+target]!=='true'} onclick={()=>void action(target)}><UiIcon name={icon} size={19}/><span>{label}</span><span class="arrow">›</span></button>{/each}<button class="hud-button" disabled={busy} onclick={()=>void invoke('set_hud_interactive',{editing:true}).catch(e=>message=String(e))}><UiIcon name="grid" size={17}/>Personalizar HUD <small>F8</small></button></nav><p role="status">{message}</p></main>
 <footer><span>Minecraft {frame.version} · {frame.username}<small>Interfaz local TP · Los mundos y conexiones los administra Minecraft.</small></span><button disabled={busy||frame.telemetry?.labels?.title_quit!=='true'} onclick={()=>void action('quit')}>Salir del juego</button><span>Minecraft © Mojang AB<small>TP LAUNCHER no está afiliado a Mojang ni Microsoft.</small></span></footer>
</section>
<style>
.title-scene{position:absolute;inset:0;pointer-events:auto;color:#f0e7fa;font:14px 'Segoe UI',sans-serif;background:radial-gradient(ellipse at 65% 25%,#58228f66,transparent 55%),radial-gradient(ellipse at 10% 80%,#85247b44,transparent 50%),#07060d;display:flex;flex-direction:column;overflow:hidden}.title-scene:before{content:'';position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(#06050c80,#06050cce),var(--scene);background-size:cover;background-position:center}.ambient{position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(#a855f70b 1px,transparent 1px),linear-gradient(90deg,#a855f70b 1px,transparent 1px);background-size:48px 48px;mask-image:radial-gradient(ellipse,black,transparent 80%)}.ambient:after{content:'';position:absolute;top:15%;left:60%;width:150px;height:300px;transform:rotate(30deg);box-shadow:0 0 140px 40px #a855f740;background:#a855f712;animation:drift 12s ease-in-out infinite alternate}.title-scene header,.title-scene footer{position:relative;z-index:1;padding:24px 32px;display:flex;align-items:center;justify-content:space-between;gap:15px}.title-scene header>span{font-size:12px;font-weight:700;letter-spacing:.15em}.title-scene i{font-style:normal;color:#a489bb;margin-left:15px;font-size:9px}.title-scene header>div{display:flex;gap:9px}.title-scene button,.tool{color:inherit;background:#ffffff05;border:1px solid #b786d538;border-radius:5px;font:inherit;padding:10px 15px;cursor:pointer}.title-scene button:hover,.tool:hover{border-color:#d589ff;background:#a855f71d}.title-scene button:disabled{opacity:.35;cursor:default}.title-scene button:focus-visible,.tool:focus-within{outline:2px solid #d946ef;outline-offset:4px}.tool{display:flex;gap:8px;align-items:center;font-size:12px}.tool input{display:none}.title-scene main{position:relative;z-index:1;margin:auto;display:grid;justify-items:center;width:min(400px,75%)}.brand{width:92px;height:106px;filter:drop-shadow(0 0 25px #9f42db66)}.edition{font-size:9px;letter-spacing:.24em;color:#b29bc3;margin-top:23px}h1{font-size:32px;letter-spacing:.13em;margin:10px 0 28px;text-shadow:0 0 35px #a855f755}.title-scene nav{display:grid;gap:9px;width:100%}.title-scene nav button{display:flex;gap:15px;align-items:center;text-align:left;padding:15px 19px;background:linear-gradient(100deg,#20122ee8,#100d17e8);border-color:#a855f755;font-size:15px}.title-scene nav button>span:nth-child(2){flex:1}.title-scene nav button.primary{background:linear-gradient(100deg,#8f37d2,#662d9a);border-color:#cb8cff99;font-weight:600}.arrow{color:#c6a3db;font-size:22px}.title-scene nav button.hud-button{justify-content:center;font-size:12px;background:#ffffff04;margin-top:7px}.hud-button small{font-size:10px;color:#b89acb}.title-scene main p{font-size:11px;line-height:1.6;color:#e4c6f6;min-height:18px;text-align:center}.title-scene footer{font-size:10px;color:#aa98b8;align-items:end}.title-scene footer>span:last-child{text-align:right}.title-scene footer small{display:block;font-size:9px;color:#786a86;margin-top:7px}.title-scene footer button{font-size:11px}@keyframes drift{to{transform:translate(-100px,30px) rotate(25deg);opacity:.3}}@media(max-height:650px){.brand{height:60px;width:52px}h1{font-size:25px;margin-bottom:16px}.edition{margin-top:10px}.title-scene nav button{padding:10px 14px}.title-scene header,.title-scene footer{padding:16px 24px}}@media(prefers-reduced-motion:reduce){.ambient:after{animation:none}}
</style>
